// Bundle entrypoint.ts into a set of module-name → source
// string records and write them under generated/ as TypeScript
// modules, each default-exporting one record. Consumers spread
// the records into the Worker Loader callback's `modules` field
// without running a build of their own.
//
// Why a record and not a single string? esbuild's bundle: true
// inlines dynamic import() targets too, which dragged the full
// just-bash command surface (python, js-exec, sqlite, curl,
// html-to-markdown, …) into a ~3 MB string. workerd parsed all
// of it on every cold start even though the default ShellWorker
// disables python/javascript/network. With splitting: true the
// dynamic chunks live next to shell.js in the modules table;
// workerd only parses a chunk the first time something imports
// it, so the cold-start cost matches the static-reachable set
// (~650 KB) and optional features stay free until used.
//
// Why several files and not one? Each optional command (curl,
// html-to-markdown, python, sqlite, js-exec) carries chunks that
// are only reachable through that command — curl's undici
// (~620 KB) and html-to-markdown's domino (~555 KB) dominate the
// bundle. Splitting them into their own generated module lets a
// consumer alias the feature out at build time
// (@cloudflare/computer/shell/<feature> → @cloudflare/computer/empty),
// dropping the feature's exclusive chunks — and its heavy
// dependency — from the uploaded Worker. shell-modules.ts spreads
// every group back together, so the default build is byte-for-byte
// what the single-file bundle produced.
//
// The generated/ output is gitignored. It's regenerated by the
// computer package's prepare / pretest / pretypecheck scripts
// so any install from this repo or downstream consumer sees a
// fresh bundle matching the source.

import { mkdir, mkdtemp, rm, writeFile } from "node:fs/promises";
import { tmpdir } from "node:os";
import { dirname, relative, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import { build } from "esbuild";

const here = dirname(fileURLToPath(import.meta.url));
// Script lives at .../backends/worker/script/build-bundle.mjs;
// the bundle target is one level up at .../backends/worker/.
const root = resolve(here, "..");
const outDir = resolve(root, "generated");

// Optional commands whose chunks are worth splitting out so a
// consumer can drop them. Keyed by the feature name used in the
// package subpath (@cloudflare/computer/shell/<feature>); the
// value lists the just-bash command names that pull the feature
// in. A chunk lands in a feature group only when that feature is
// the sole optional owner of it and core can't reach it; anything
// shared with core or with a second feature stays in core so
// dropping one feature never breaks another.
const OPTIONAL_FEATURES = {
  curl: ["curl"],
  "html-to-markdown": ["html-to-markdown"],
  python: ["python3", "python"],
  sqlite: ["sqlite3"],
  "js-exec": ["js-exec", "node"],
};

await mkdir(outDir, { recursive: true });

// esbuild's code-splitting requires an outdir to compute chunk
// paths against. Use a scratch directory so the build output is
// transient; we read result.outputFiles and never touch disk
// for the .js fragments themselves.
const scratch = await mkdtemp(resolve(tmpdir(), "shell-bundle-"));

let result;
try {
  result = await build({
    entryPoints: { shell: resolve(root, "entrypoint.ts") },
    bundle: true,
    write: false,
    splitting: true,
    outdir: scratch,
    format: "esm",
    target: "es2022",
    platform: "neutral",
    mainFields: ["module", "main"],
    conditions: ["workerd", "worker", "import"],
    // Flat chunk names so the modules table keys stay simple.
    // shell.js holds the entrypoint; everything else lands as
    // chunk-<hash>.js next to it.
    entryNames: "[name]",
    chunkNames: "chunk-[hash]",
    external: [
      // workerd built-ins resolved at runtime.
      "cloudflare:workers",
      "cloudflare:sockets",
      "node:*",
      // Bare node module names that show up via transitive deps;
      // the nodejs_compat polyfill resolves them inside workerd.
      "util",
      "util/types",
      "stream",
      "buffer",
      "path",
      "fs",
      "fs/promises",
      "events",
      "crypto",
      "url",
      "os",
      "assert",
      "querystring",
      "string_decoder",
      // Optional native compression deps just-bash's `tar` command
      // reaches through `await import(...)` blocks wrapped in
      // try/catch. Leaving them external surfaces a clean
      // "module not found" error if a script reaches for one.
      "node-liblzma",
      "@mongodb-js/zstd",
      // seek-bzip is statically imported by just-bash's tar
      // command for .bz2 support. Leaving it external preserves
      // the bare `import seekBzip from "seek-bzip"` in the emitted
      // bundle; SHELL_RUNTIME_MODULES carries a stub the host
      // Worker spreads into the loader's modules table so workerd
      // resolves the import at module load time.
      "seek-bzip",
    ],
    // Treat any stray .node native binding the resolver still
    // surfaces as an empty module. Belt-and-braces for transitive
    // deps that pull in native code through a deeper path.
    loader: { ".node": "empty" },
    // just-bash does `createRequire(import.meta.url)` at module
    // init time. Workerd doesn't populate import.meta.url for
    // string-loaded Dynamic Worker modules, so the call throws.
    // Substitute a stable file URL at bundle time; createRequire
    // is fine with any absolute file URL, and just-bash never
    // actually require()s anything at runtime — the call sites
    // are dead code in the workerd target.
    define: {
      "import.meta.url": JSON.stringify("file:///shell.js"),
    },
  });
} finally {
  // The scratch outdir is only used to anchor relative paths.
  // No files were written (write: false), so removing it is
  // best-effort cleanup of the empty directory.
  await rm(scratch, { recursive: true, force: true });
}

if (!result.outputFiles || result.outputFiles.length === 0) {
  throw new Error("build-bundle: esbuild returned no output");
}

// Collect each emitted file into a modules record keyed by its
// scratch-relative path. esbuild writes the entry as shell.js and
// chunks as chunk-<hash>.js per entryNames / chunkNames above.
const modules = {};
for (const file of result.outputFiles) {
  const name = relative(scratch, file.path).split(/[\\/]/).join("/");
  modules[name] = file.text;
}

if (!modules["shell.js"]) {
  throw new Error(
    `build-bundle: expected shell.js in output, got: ${Object.keys(modules).join(", ")}`,
  );
}

const partition = partitionModules(modules);

// Emit one generated file per group. shell-modules.ts imports
// each by its @cloudflare/computer/shell/<group> subpath and
// spreads them back together.
const groupNames = ["core", ...Object.keys(OPTIONAL_FEATURES)];
let totalBytes = 0;
for (const group of groupNames) {
  const names = (partition[group] ?? []).sort();
  const record = {};
  for (const name of names) {
    record[name] = { js: modules[name] };
    totalBytes += modules[name].length;
  }
  const header =
    `// Generated by script/build-bundle.mjs — do not edit.\n` +
    `// Shell modules exclusive to the "${group}" feature group.\n`;
  const body = `export default Object.freeze(${JSON.stringify(
    record,
    null,
    2,
  )}) as Readonly<Record<string, { js: string }>>;\n`;
  await writeFile(resolve(outDir, `${group}.ts`), `${header}\n${body}`);
}

const coreCount = (partition.core ?? []).length;
const mainBytes = modules["shell.js"].length;
const featureSummary = Object.keys(OPTIONAL_FEATURES)
  .map((f) => `${f} ${(partition[f] ?? []).length}`)
  .join(", ");
console.log(
  `Wrote ${outDir} (core ${coreCount} modules, shell.js ${mainBytes} bytes, ` +
    `features: ${featureSummary}, total ${totalBytes} bytes)`,
);

// Assign every emitted module to exactly one group: "core" or one
// of the OPTIONAL_FEATURES keys. A module belongs to a feature
// only when that feature is its sole reacher and core can't reach
// it; everything else — shared chunks, chunks reachable from a
// kept command, the shell.js entry itself — stays in core.
function partitionModules(mods) {
  const names = Object.keys(mods);
  const staticEdges = new Map();
  const dynamicEdges = new Map();
  for (const name of names) {
    staticEdges.set(name, moduleEdges(mods[name], /* dynamic */ false));
    dynamicEdges.set(name, moduleEdges(mods[name], /* dynamic */ true));
  }

  const closure = (starts, followDynamic) => {
    const seen = new Set();
    const stack = [...starts];
    while (stack.length > 0) {
      const cur = stack.pop();
      if (seen.has(cur) || !mods[cur]) continue;
      seen.add(cur);
      for (const next of staticEdges.get(cur) ?? []) stack.push(next);
      if (followDynamic) for (const next of dynamicEdges.get(cur) ?? []) stack.push(next);
    }
    return seen;
  };

  const registry = parseCommandChunks(mods["shell.js"]);
  const undici = parseNetworkChunk(mods["shell.js"]);

  const optionalCommands = new Set(Object.values(OPTIONAL_FEATURES).flat());

  // Core reach: everything statically pulled by shell.js (the
  // always-parsed entry) plus the full closure of every command
  // that isn't optional. Dynamic edges out of shell.js are the
  // per-command import() fan-out — following them would drag every
  // optional chunk into core, so core uses shell.js's static edges
  // only.
  const coreReach = closure(["shell.js"], /* dynamic */ false);
  for (const [command, chunk] of Object.entries(registry)) {
    if (!optionalCommands.has(command)) {
      for (const m of closure([chunk], /* dynamic */ true)) coreReach.add(m);
    }
  }

  // Each feature reaches the full closure of its command entry
  // chunks. curl also owns the network agent chunk (undici), which
  // shell.js imports lazily from its own body rather than through
  // the curl command chunk.
  const featureReach = new Map();
  for (const [feature, commands] of Object.entries(OPTIONAL_FEATURES)) {
    const roots = commands.map((c) => registry[c]).filter(Boolean);
    if (feature === "curl" && undici) roots.push(undici);
    featureReach.set(feature, closure(roots, /* dynamic */ true));
  }

  const partition = { core: [] };
  for (const feature of Object.keys(OPTIONAL_FEATURES)) partition[feature] = [];
  for (const name of names) {
    const owners = [];
    if (coreReach.has(name)) owners.push("core");
    for (const feature of Object.keys(OPTIONAL_FEATURES)) {
      if (featureReach.get(feature).has(name)) owners.push(feature);
    }
    const optionalOwners = owners.filter((o) => o !== "core");
    if (!owners.includes("core") && optionalOwners.length === 1) {
      partition[optionalOwners[0]].push(name);
    } else {
      partition.core.push(name);
    }
  }
  return partition;
}

// Import specifiers a module references. Static edges are the
// top-level `import`/`export … from` and bare side-effect
// imports; dynamic edges are `import(...)` calls. Only relative
// chunk specifiers matter — externals resolve at runtime.
function moduleEdges(source, dynamic) {
  const targets = new Set();
  if (dynamic) {
    for (const m of source.matchAll(/import\("(\.\/[^"]+)"\)/g)) {
      targets.add(m[1].replace(/^\.\//, ""));
    }
    return targets;
  }
  for (const m of source.matchAll(/(?:import|export)[^;]*?from\s*"(\.\/[^"]+)"/g)) {
    targets.add(m[1].replace(/^\.\//, ""));
  }
  for (const m of source.matchAll(/import\s*"(\.\/[^"]+)"/g)) {
    targets.add(m[1].replace(/^\.\//, ""));
  }
  return targets;
}

// Map each just-bash command to the chunk its lazy loader
// imports. The registry entries look like
//   { name: "curl", load: async () => (await import("./chunk-…js")).curlCommand }
function parseCommandChunks(shellSource) {
  const registry = {};
  const re =
    /\{\s*name:\s*"([^"]+)",\s*load:\s*async\s*\(\)\s*=>\s*\(await import\("(\.\/chunk-[^"]+)"\)\)/g;
  for (const m of shellSource.matchAll(re)) {
    registry[m[1]] = m[2].replace(/^\.\//, "");
  }
  return registry;
}

// Find the chunk shell.js lazily imports to build its network
// Agent. just-bash loads undici on demand from its own body
// (`await import("./chunk-…"), new X.Agent(`), not through the
// curl command chunk, so it needs to be attributed to curl by
// hand.
function parseNetworkChunk(shellSource) {
  const m = shellSource.match(
    /await import\("(\.\/chunk-[^"]+)"\),\s*\w+\s*=\s*new\s+\w+\.Agent\(/,
  );
  return m ? m[1].replace(/^\.\//, "") : null;
}
